import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type CountdownDownloadProps = Record<string, any>;

const BACKGROUND_NODE_COUNT = 35;

const getWeb3Icon = (type: number, color: string) => {
  switch (type) {
    case 0: // Diamond / Eth
      return (
        <svg viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
          <path d="M11.999 3.167L5.536 13.91l6.463 3.826 6.463-3.826-6.463-10.743z" />
          <path d="M11.999 18.91l-6.463-3.826 6.463 8.749 6.463-8.749-6.463 3.826z" />
        </svg>
      );
    case 1: // Network / Nodes
      return (
        <svg viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
          <circle cx="18" cy="5" r="3" />
          <circle cx="6" cy="12" r="3" />
          <circle cx="18" cy="19" r="3" />
          <line x1="8.59" y1="13.51" x2="15.42" y2="17.49" />
          <line x1="15.41" y1="6.51" x2="8.59" y2="10.49" />
        </svg>
      );
    case 2: // Graph / Chart
      return (
        <svg viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
          <line x1="18" y1="20" x2="18" y2="10" />
          <line x1="12" y1="20" x2="12" y2="4" />
          <line x1="6" y1="20" x2="6" y2="14" />
        </svg>
      );
    default: // Blockchain / Cube
      return (
        <svg viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
          <path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z" />
          <polyline points="3.27 6.96 12 12.01 20.73 6.96" />
          <line x1="12" y1="22.08" x2="12" y2="12" />
        </svg>
      );
  }
};

const CountdownDownload: React.FC<CountdownDownloadProps> = ({
  backgroundColor = "#0d1117",
  transparentBackground = false,
  durationInSeconds = 8,
  timerStartSeconds = 300,
  timerColor = "#ffffff",
  iconColor = "#3b82f6",
  cursorColor = "#111111",
  web3IconColor = "#8b5cf6",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Frame math for sequenced animation
  const actionDurationSeconds = 4;
  const countdownDurationFrames = Math.max(30, (durationInSeconds - actionDurationSeconds) * fps);
  
  const timerOutStart = countdownDurationFrames + 10;
  const iconInStart = timerOutStart + 15;
  const mouseInStart = iconInStart + 20;
  const clickStart = mouseInStart + 30;

  // Web3 Background Nodes Data
  const backgroundNodes = useMemo(() => {
    return new Array(BACKGROUND_NODE_COUNT).fill(0).map((_, i) => {
      return {
        id: i,
        startX: random(`x-${i}`) * width,
        startY: random(`y-${i}`) * height,
        type: Math.floor(random(`type-${i}`) * 4),
        baseScale: 0.8 + random(`scale-${i}`) * 1.5,
        pulseSpeed: 15 + random(`speed-${i}`) * 30,
        pulseOffset: random(`offset-${i}`) * Math.PI * 2,
      };
    });
  }, [width, height]);

  // --- 1. Timer Logic ---
  const timerValue = interpolate(
    frame,
    [0, countdownDurationFrames],
    [timerStartSeconds, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const formatTime = (totalSecs: number) => {
    const m = Math.floor(totalSecs / 60);
    const s = Math.floor(totalSecs % 60);
    return `${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`;
  };

  const timerScale = interpolate(frame, [timerOutStart, timerOutStart + 15], [1, 0.8], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const timerOpacity = interpolate(frame, [timerOutStart, timerOutStart + 10], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- 2. Icon Logic ---
  const iconScaleBase = spring({
    fps,
    frame: frame - iconInStart,
    config: { damping: 12, stiffness: 120 },
  });

  const iconClickDown = interpolate(frame, [clickStart, clickStart + 3], [0, 1], { 
    extrapolateRight: "clamp", extrapolateLeft: "clamp" 
  });
  const iconClickUp = interpolate(frame, [clickStart + 3, clickStart + 8], [0, 1], { 
    extrapolateRight: "clamp", extrapolateLeft: "clamp" 
  });
  
  const iconClickScale = 1 - iconClickDown * 0.15 + iconClickUp * 0.15;
  const finalIconScale = iconScaleBase * iconClickScale;

  // --- 3. Mouse Logic ---
  const mouseProgress = spring({
    fps,
    frame: frame - mouseInStart,
    config: { damping: 14, stiffness: 100 },
  });

  const startMouseX = width * 0.7;
  const startMouseY = height * 0.8;
  const targetMouseX = width / 2;
  const targetMouseY = height / 2;

  const mouseX = interpolate(mouseProgress, [0, 1], [startMouseX, targetMouseX]);
  const mouseY = interpolate(mouseProgress, [0, 1], [startMouseY, targetMouseY]);

  const mouseClickDown = interpolate(frame, [clickStart, clickStart + 2], [0, 1], { 
    extrapolateRight: "clamp", extrapolateLeft: "clamp" 
  });
  const mouseClickUp = interpolate(frame, [clickStart + 2, clickStart + 6], [0, 1], { 
    extrapolateRight: "clamp", extrapolateLeft: "clamp" 
  });
  
  const mouseClickScale = 1 - mouseClickDown * 0.2 + mouseClickUp * 0.2;
  
  const mouseOpacity = interpolate(frame, [mouseInStart, mouseInStart + 5], [0, 1], { 
    extrapolateRight: "clamp", extrapolateLeft: "clamp" 
  });

  // --- SVGs ---
  const DownloadIcon = (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="200"
      height="200"
      viewBox="0 0 24 24"
      fill="none"
      stroke={iconColor}
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ filter: "drop-shadow(0px 10px 20px rgba(0,0,0,0.3))" }}
    >
      <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
      <polyline points="7 10 12 15 17 10" />
      <line x1="12" y1="15" x2="12" y2="3" />
    </svg>
  );

  const CursorIcon = (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="80"
      height="80"
      viewBox="0 0 24 24"
      fill={cursorColor}
      stroke="#ffffff"
      strokeWidth="1.5"
      style={{ filter: "drop-shadow(0px 8px 12px rgba(0,0,0,0.4))" }}
    >
      <path d="M3 3l7.07 16.97 2.51-7.39 7.39-2.51L3 3z" />
    </svg>
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", overflow: "hidden" }}>
      
      {/* Web3 Icons Background Layer */}
      {backgroundNodes.map((node) => {
        // Continuous appear/disappear pulse
        const pulseOp = interpolate(
          Math.sin(frame / node.pulseSpeed + node.pulseOffset),
          [-1, 1],
          [0.05, 0.4]
        );

        // Convergence into center when timer ends
        const convergeProgress = spring({
          fps,
          frame: frame - timerOutStart,
          config: { damping: 14, stiffness: 90 },
        });

        // Fade out perfectly as they hit the center
        const convergenceFade = interpolate(
          frame,
          [timerOutStart, timerOutStart + 15],
          [1, 0],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        const currentX = interpolate(convergeProgress, [0, 1], [node.startX, width / 2]);
        const currentY = interpolate(convergeProgress, [0, 1], [node.startY, height / 2]);
        const currentScale = interpolate(convergeProgress, [0, 1], [node.baseScale, 0]);
        const currentRotation = interpolate(convergeProgress, [0, 1], [0, 180]);
        
        const finalOpacity = pulseOp * convergenceFade;

        return (
          <div
            key={node.id}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: 80,
              height: 80,
              marginLeft: -40,
              marginTop: -40,
              transform: `translate(${currentX}px, ${currentY}px) scale(${currentScale}) rotate(${currentRotation}deg)`,
              opacity: finalOpacity,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              transition: "none",
            }}
          >
            {getWeb3Icon(node.type, web3IconColor)}
          </div>
        );
      })}

      {/* Timer Layer */}
      <AbsoluteFill
        style={{
          opacity: timerOpacity,
          transform: `scale(${timerScale})`,
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        <div
          style={{
            fontFamily: robotoMonoFamily,
            fontSize: 260,
            fontWeight: 700,
            color: timerColor,
            textShadow: "0 10px 40px rgba(0,0,0,0.6)",
            letterSpacing: "-0.05em",
            transition: "none",
          }}
        >
          {formatTime(timerValue)}
        </div>
      </AbsoluteFill>

      {/* Download Icon Layer */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        <div
          style={{
            transform: `scale(${finalIconScale})`,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transition: "none",
          }}
        >
          {DownloadIcon}
          
          {/* Click Ripple Effect */}
          {frame > clickStart && (
            <div
              style={{
                position: "absolute",
                width: 200,
                height: 200,
                borderRadius: "50%",
                border: `4px solid ${iconColor}`,
                opacity: interpolate(frame, [clickStart, clickStart + 20], [0.8, 0], { extrapolateRight: "clamp" }),
                transform: `scale(${interpolate(frame, [clickStart, clickStart + 20], [1, 2], { extrapolateRight: "clamp" })})`,
                transition: "none",
              }}
            />
          )}
        </div>
      </AbsoluteFill>

      {/* Mouse Cursor Layer */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          opacity: mouseOpacity,
          transform: `translate(${mouseX}px, ${mouseY}px) scale(${mouseClickScale})`,
          transformOrigin: "top left",
          zIndex: 10,
          transition: "none",
        }}
      >
        {CursorIcon}
      </div>

    </AbsoluteFill>
  );
};

export default CountdownDownload;